export const JOURNAL_GUIDES: BlogArticle[] = groups.flatMap(([category, guides]) => guides.map(
  ([slug, title, description, link, relatedArticles, ...sections]) => {
    const wordCount = sections.map(([, body]) => body).join(' ').split(/\s+/).length;
    return {
      slug,
      title,
      description,
      keywords: [],
      category,
      author: 'Nara Charm',
      publishedAt: '2026-11-18',
      updatedAt: revisedGuides.has(slug) ? '2026-11-19' : '2026-11-18',
      readingTime: `${Math.max(1, Math.ceil(wordCount / 220))} min read`,
      relatedProducts: guideProducts[slug] ?? [],
      relatedArticles,
      editorialLink: link,
      content: sections.map(([heading, body]) => ({ heading, body: [body] })),
    };
  },
));
